import os
for fn in ['/proc/kcore']:
    fd=os.open(fn, os.O_RDONLY)
    for off in [0, 0x1000, 0x100000, 0x1000000]:
        try:
            os.lseek(fd, off, os.SEEK_SET)
            d=os.read(fd, 32)
            print('off',hex(off),'len',len(d),'hex',d.hex())
        except Exception as e:
            print('off',hex(off),'ERR',repr(e))
    os.close(fd)
